(15,3,1,'2026-05-22','Banking Domain Vocabulary and Java Mapping','Establish foundational English vocabulary for core banking concepts and learn how to describe their translation into Java classes and data types.','foundation','ready',9,'2026-05-22 20:02:39',NULL,NULL,'2026-05-22 20:02:25','2026-05-22 20:02:39'),
