INSERT INTO `learning_plans` VALUES
(1,6,'android development','English','intermediate',7,'need to prepare for job interview, I need to learn jetpack compose','{\"days\":[{\"day\":1,\"title\":\"Declarative UI Paradigm & Core Compose Concepts\",\"focus\":\"Transition from imperative XML to declarative UI, mastering composable functions, and understanding the basic lifecycle of a composable.\",\"phase\":\"foundation\",\"objectives\":[\"Explain the difference between imperative and declarative UI paradigms in Android.\",\"Create basic Composable functions and understand how recomposition is triggered.\",\"Implement basic state tracking using \'remember\' and \'mutableStateOf\' within a single screen.\"]},{\"day\":2,\"title\":\"Layouts, Modifiers, and Lazy Components\",\"focus\":\"Mastering UI positioning in Jetpack Compose using standard layouts, modifiers, and efficient list rendering.\",\"phase\":\"foundation\",\"objectives\":[\"Structure UI screens using Row, Column, and Box layouts.\",\"Apply and chain Modifiers correctly to control sizing, padding, and user interactions.\",\"Implement efficient scrollable lists using LazyColumn and LazyRow with custom item keys.\"]},{\"day\":3,\"title\":\"State Management & ViewModel Integration\",\"focus\":\"Deep dive into unidirectional data flow (UDF), state hoisting, and integrating Jetpack ViewModels with Compose.\",\"phase\":\"building\",\"objectives\":[\"Apply state hoisting to make composables stateless and reusable, building on Day 1\'s basic state concepts.\",\"Integrate Android Architecture Components by collecting state from a ViewModel using \'collectAsStateWithLifecycle\'.\",\"Design a robust Unidirectional Data Flow (UDF) pattern for a single-screen feature.\"]},{\"day\":4,\"title\":\"Compose Navigation & Side Effects\",\"focus\":\"Implementing multi-screen navigation using the Compose Navigation component and managing asynchronous side effects.\",\"phase\":\"building\",\"objectives\":[\"Set up a NavHost and implement type-safe navigation between screens, building on Day 2\'s layout structures.\",\"Pass arguments securely between destinations using the Compose Navigation library.\",\"Utilize side-effect APIs like \'LaunchedEffect\' and \'rememberCoroutineScope\' to handle asynchronous events, building on Day 3\'s ViewModel state.\"]},{\"day\":5,\"title\":\"Clean Architecture & Dependency Injection with Hilt\",\"focus\":\"Structuring a production-ready Android application using Clean Architecture, MVVM, and Hilt dependency injection in Compose.\",\"phase\":\"practice\",\"objectives\":[\"Architect a multi-layered project separating UI, Domain, and Data layers, building on Day 3\'s state hoisting and ViewModel integration.\",\"Inject dependencies into ViewModels and Composables using Hilt and \'@HiltViewModel\'.\",\"Implement a repository pattern to fetch mock network data and expose it to the UI layer, building on Day 4\'s side-effect handling.\"]},{\"day\":6,\"title\":\"Compose Performance Optimization & Animations\",\"focus\":\"Identifying recomposition bottlenecks, optimizing UI rendering, and implementing fluid animations.\",\"phase\":\"practice\",\"objectives\":[\"Diagnose and fix unnecessary recompositions using \'derivedStateOf\' and \'rememberUpdatedState\', building on Day 1\'s recomposition fundamentals.\",\"Optimize list rendering performance for complex layouts, building on Day 2\'s LazyColumn concepts.\",\"Implement smooth transitions and micro-interactions using \'animateContentSize\' and \'AnimatedVisibility\'.\"]},{\"day\":7,\"title\":\"Interview Simulation, System Design & Testing\",\"focus\":\"Preparing for technical interview questions, writing UI tests for composables, and solving system design challenges.\",\"phase\":\"mastery\",\"objectives\":[\"Write robust UI tests for composables using ComposeTestRule and semantic finders, building on Day 5\'s Clean Architecture structure.\",\"Solve common Android system design interview questions involving offline-first capabilities and real-time UI updates.\",\"Articulate Compose performance best practices and architectural decisions in a mock interview format, synthesizing concepts from Day 3 through Day 6.\"]}]}','active','2026-05-22','2026-05-22 19:49:44','2026-05-22 19:49:44'),
(2,4,'kotlin language','English','intermediate',7,NULL,'{\"days\":[{\"day\":1,\"title\":\"Kotlin Syntax and Type System Basics\",\"focus\":\"Learn the essential English vocabulary for describing Kotlin\'s basic syntax, variable declarations, and its core feature of null safety.\",\"phase\":\"foundation\",\"objectives\":[\"Identify and pronounce key Kotlin terms like \'read-only\', \'mutable\', and \'nullable\'\",\"Explain the difference between \'val\' and \'var\' using precise English verbs\",\"Describe the concept of \'NullPointerException\' prevention in English\"]},{\"day\":2,\"title\":\"Describing Functions and Control Flow\",\"focus\":\"Master the English terminology used to explain Kotlin functions, parameters, return types, and conditional expressions.\",\"phase\":\"foundation\",\"objectives\":[\"Describe function signatures using terms like \'arguments\', \'parameters\', and \'return type\'\",\"Explain conditional expressions (if-else, when) as expressions rather than statements in English\",\"Verbally trace basic execution flow in a Kotlin function using sequential transition words\"]},{\"day\":3,\"title\":\"OOP and Functional Concepts in Kotlin\",\"focus\":\"Build vocabulary around Kotlin\'s object-oriented and functional programming features, building on Day 1\'s type system and Day 2\'s functions.\",\"phase\":\"building\",\"objectives\":[\"Explain Kotlin \'data classes\' and \'properties\' using precise technical English\",\"Describe lambda expressions and higher-order functions, referencing Day 2\'s function concepts\",\"Discuss class inheritance and interfaces using appropriate relational verbs\"]},{\"day\":4,\"title\":\"Explaining Advanced Kotlin Features\",\"focus\":\"Learn to explain complex Kotlin-specific features like coroutines, extension functions, and smart casts, building on Day 3\'s OOP and functional concepts.\",\"phase\":\"building\",\"objectives\":[\"Explain the concept of \'asynchronous programming\' and \'coroutines\' using clear analogies\",\"Describe how \'extension functions\' extend class behavior without inheritance, referencing Day 3 OOP concepts\",\"Articulate the mechanism of \'smart casts\' and how they relate to Day 1\'s null safety\"]},{\"day\":5,\"title\":\"Writing KDoc and Technical Documentation\",\"focus\":\"Practice writing clear, professional English documentation and comments for Kotlin code, utilizing syntax terms from Day 1 and class concepts from Day 3.\",\"phase\":\"practice\",\"objectives\":[\"Write standard KDoc comments for classes and functions using professional technical English\",\"Draft clear, concise inline comments explaining \'why\' code is written a certain way\",\"Document nullability expectations and exception handling using precise English adjectives\"]},{\"day\":6,\"title\":\"Conducting Code Reviews and PR Discussions\",\"focus\":\"Practice professional English communication for Pull Requests, code reviews, and technical debates, building on Day 4\'s advanced features and Day 5\'s documentation standards.\",\"phase\":\"practice\",\"objectives\":[\"Write constructive Pull Request descriptions explaining code changes clearly\",\"Formulate polite, professional suggestions in English during peer code reviews\",\"Discuss performance trade-offs of coroutines (referencing Day 4) and syntax choices in English\"]},{\"day\":7,\"title\":\"Technical Interviews and Architectural Discussions\",\"focus\":\"Master the ability to explain high-level architectural decisions, design patterns, and Kotlin-specific advantages in professional English, synthesizing concepts from Days 3, 4, and 6.\",\"phase\":\"mastery\",\"objectives\":[\"Deliver a structured verbal comparison of Kotlin vs Java using comparative English structures\",\"Explain architectural patterns (like MVVM or Clean Architecture) in Kotlin using advanced technical vocabulary\",\"Defend technical choices (such as using coroutines from Day 4 or data classes from Day 3) in a mock technical interview scenario\"]}]}','active','2026-05-22','2026-05-22 19:58:32','2026-05-22 19:58:32'),
(3,7,'java for banking','English','intermediate',7,NULL,'{\"days\":[{\"day\":1,\"title\":\"Banking Domain Vocabulary and Java Mapping\",\"focus\":\"Establish foundational English vocabulary for core banking concepts and learn how to describe their translation into Java classes and data types.\",\"phase\":\"foundation\",\"objectives\":[\"Identify and use English terminology for ledgers, transactions, and account types.\",\"Explain in English how to map financial concepts to Java primitives and objects (e.g., using BigDecimal for currency).\"]},{\"day\":2,\"title\":\"Discussing Security, Compliance, and ACID Properties\",\"focus\":\"Develop the English vocabulary needed to discuss security standards, regulatory compliance, and database transaction properties in a banking context.\",\"phase\":\"foundation\",\"objectives\":[\"Describe compliance standards like PCI-DSS and GDPR using appropriate professional English.\",\"Explain the ACID properties of banking transactions and how Java frameworks like Spring manage them.\"]},{\"day\":3,\"title\":\"Describing API Design and Payment Gateway Integration\",\"focus\":\"Building on the core banking terminology from Day 1, learn to describe RESTful API design and payment gateway integrations in English.\",\"phase\":\"building\",\"objectives\":[\"Use precise technical English to explain API endpoints, request\\/response payloads, and HTTP status codes for financial transactions.\",\"Describe the step-by-step integration flow of a payment gateway using sequence-related transition words.\"]},{\"day\":4,\"title\":\"Explaining Concurrency and High-Throughput Processing\",\"focus\":\"Building on the transactional concepts from Day 2, master the English phrasing required to explain multithreading, race conditions, and thread safety in Java banking applications.\",\"phase\":\"building\",\"objectives\":[\"Articulate the risks of race conditions in financial ledgers and how to prevent them using Java concurrency utilities.\",\"Explain the concept of thread safety and asynchronous processing to non-technical stakeholders in clear English.\"]},{\"day\":5,\"title\":\"Conducting Code Reviews and Explaining Bug Fixes\",\"focus\":\"Applying the API design concepts from Day 3 and concurrency concepts from Day 4, practice constructive English communication during code reviews and bug debugging sessions.\",\"phase\":\"practice\",\"objectives\":[\"Formulate polite, constructive feedback in English during a peer code review of a Java banking module.\",\"Explain a complex financial bug (such as a double-spending vulnerability) and its resolution using clear, sequential English.\"]},{\"day\":6,\"title\":\"Writing Technical Documentation for Banking Modules\",\"focus\":\"Utilizing the debugging vocabulary from Day 5 and API concepts from Day 3, practice writing clear, professional technical documentation and system architecture summaries in English.\",\"phase\":\"practice\",\"objectives\":[\"Draft a professional README and API documentation in English for a Java-based microservice.\",\"Write clear, concise commit messages and pull request descriptions following industry standard English templates.\"]},{\"day\":7,\"title\":\"System Design Presentation and Stakeholder Communication\",\"focus\":\"Synthesizing the documentation skills from Day 6 and the technical discussions from Days 4 and 5, deliver a professional English presentation on a Java banking system design.\",\"phase\":\"mastery\",\"objectives\":[\"Present a Java-based banking system architecture to stakeholders, justifying technical choices using persuasive English.\",\"Handle challenging, spontaneous technical questions in English regarding system scalability, security, and fault tolerance.\"]}]}','active','2026-05-22','2026-05-22 20:02:25','2026-05-22 20:02:25'),
(4,9,'Python','English','intermediate',7,NULL,'{\"days\":[{\"day\":1,\"title\":\"Pythonic Code & Core Terminology\",\"focus\":\"Master intermediate data structures and idiomatic Python (PEP 8) while learning the precise English terminology used to describe clean code.\",\"phase\":\"foundation\",\"objectives\":[\"Identify and use list comprehensions, dict comprehensions, and generator expressions\",\"Explain the concept of \'Pythonic\' code using professional English development terms\",\"Apply PEP 8 style guidelines to improve code readability\"]},{\"day\":2,\"title\":\"Functional Programming & Docstrings\",\"focus\":\"Explore functional programming paradigms in Python and learn how to write professional English documentation and docstrings.\",\"phase\":\"foundation\",\"objectives\":[\"Implement lambda functions, map, filter, and zip in data processing pipelines\",\"Write clear, standard-compliant docstrings in English using Sphinx or Google style\",\"Describe functional programming concepts to peers using accurate technical English\"]},{\"day\":3,\"title\":\"Advanced OOP & Class Design\",\"focus\":\"Deepen your understanding of Object-Oriented Programming, building on the clean code and functional principles from Days 1 and 2 to design robust classes.\",\"phase\":\"building\",\"objectives\":[\"Implement custom classes with inheritance, properties, and dunder methods\",\"Explain OOP design patterns (like encapsulation and polymorphism) in English\",\"Refactor basic scripts into structured, object-oriented code\"]},{\"day\":4,\"title\":\"Exception Handling & Logging\",\"focus\":\"Learn to handle errors gracefully and implement logging, building on the OOP structures from Day 3 to create resilient applications.\",\"phase\":\"building\",\"objectives\":[\"Create custom exception classes and implement try-except-finally blocks\",\"Configure the logging module to track application behavior instead of using print statements\",\"Write clear English log messages and error descriptions for troubleshooting\"]},{\"day\":5,\"title\":\"API Integration & Data Serialization\",\"focus\":\"Practice connecting to external web services and handling JSON data, utilizing the error handling and logging techniques mastered in Day 4.\",\"phase\":\"practice\",\"objectives\":[\"Perform HTTP requests using the requests library and handle status codes\",\"Serialize and deserialize JSON data structures efficiently\",\"Document API integration steps and write English comments explaining external dependencies\"]},{\"day\":6,\"title\":\"Unit Testing & Code Quality\",\"focus\":\"Write automated tests for your code, building on the API integration from Day 5 and OOP from Day 3 to ensure software reliability.\",\"phase\":\"practice\",\"objectives\":[\"Write unit tests using the unittest or pytest framework\",\"Mock external API calls to isolate test cases\",\"Formulate constructive English feedback for code reviews and test assertions\"]},{\"day\":7,\"title\":\"Capston Project & Technical Presentation\",\"focus\":\"Synthesize all skills from Days 1-6 by building a complete command-line application and presenting its architecture in professional English.\",\"phase\":\"mastery\",\"objectives\":[\"Develop a modular Python application integrating OOP, API calls, error handling, and testing\",\"Create a professional README.md file in English explaining installation and usage\",\"Deliver a mock technical presentation explaining your code design and architectural choices in English\"]}]}','active','2026-05-23','2026-05-23 05:46:34','2026-05-23 05:46:34');
