INSERT INTO `lessons` VALUES
(1,2,'how to code on python','English','Coding in Python for Beginners','{\"topic\":\"how to code on python\",\"language\":\"English\",\"title\":\"Coding in Python for Beginners\",\"sections\":[{\"heading\":\"Vocabulary Terms\",\"body\":\"Syntax: The rules that define how a Python program is written.\\nExample: Python syntax is known for being clean and easy to read.\\n\\nVariable: A container used to store data values in a program.\\nExample: You can create a variable to store a user\'s name.\\n\\nFunction: A block of reusable code that performs a specific task.\\nExample: The print function displays text on the screen.\\n\\nLoop: A block of code that repeats a set of instructions.\\nExample: Use a for loop to print numbers from one to ten.\\n\\nDebug: To find and fix errors in your computer code.\\nExample: I need to debug my code because it keeps crashing.\"},{\"heading\":\"Useful Phrases\",\"body\":\"1. How do I run this Python script?\\n2. I am getting a syntax error on line five.\\n3. You need to define the variable first.\\n4. Let us write a function to automate this task.\\n5. Make sure to indent your code correctly.\"}],\"exercises\":{\"fill_in_the_blanks\":[],\"translate_phrase\":[],\"answer_question\":[],\"multiple_choice\":[{\"prompt\":\"Choose the correct word to complete the sentence.\",\"question\":\"If your code has an error, you need to ... it.\",\"options\":[\"A) debug\",\"B) loop\",\"C) variable\",\"D) syntax\"],\"correct_answer\":\"A) debug\",\"explanation\":\"Debugging means finding and fixing errors in your code.\"},{\"prompt\":\"Identify the term based on the definition.\",\"question\":\"What is a container used to store data values called?\",\"options\":[\"A) A loop\",\"B) A variable\",\"C) A syntax\",\"D) A function\"],\"correct_answer\":\"B) A variable\",\"explanation\":\"A variable stores data values that can be used and changed in a program.\"},{\"prompt\":\"Choose the best phrase for the situation.\",\"question\":\"Your code is not working because of a typo. What should you say?\",\"options\":[\"A) I have a syntax error.\",\"B) I need to run the script.\",\"C) Let us write a function.\",\"D) Define the variable first.\"],\"correct_answer\":\"A) I have a syntax error.\",\"explanation\":\"A syntax error occurs when the code violates the grammar rules of the programming language.\"},{\"prompt\":\"Choose the correct term.\",\"question\":\"Which of these is a reusable block of code that performs a task?\",\"options\":[\"A) Loop\",\"B) Syntax\",\"C) Function\",\"D) Debug\"],\"correct_answer\":\"C) Function\",\"explanation\":\"A function is a block of organized, reusable code used to perform a single action.\"},{\"prompt\":\"Choose the correct word to complete the sentence.\",\"question\":\"Python uses ... to group blocks of code instead of curly brackets.\",\"options\":[\"A) loops\",\"B) indentation\",\"C) variables\",\"D) debugging\"],\"correct_answer\":\"B) indentation\",\"explanation\":\"Indentation is required in Python to define the structure and nesting of code blocks.\"}]}}','2026-05-22 15:54:40',0,NULL),
(2,4,'how to learn korean','English','Practical Steps to Learn Korean','{\"topic\":\"how to learn korean\",\"language\":\"English\",\"title\":\"Practical Steps to Learn Korean\",\"sections\":[{\"heading\":\"Key Vocabulary\",\"body\":\"Hangul: The native alphabet of the Korean language.\\nExample: You should learn Hangul before memorizing vocabulary.\\n\\nSyllable: A unit of pronunciation containing a vowel and usually a consonant.\\nExample: Korean words are written in blocks where each block is a syllable.\\n\\nRomanization: Spelling Korean words using the Latin alphabet.\\nExample: Romanization helps beginners, but you should transition to Hangul quickly.\\n\\nHonorifics: Special words or endings used to show respect to the listener.\\nExample: Korean honorifics depend on the age and status of the person you talk to.\\n\\nImmersion: Surrounding yourself with the target language through media and conversation.\\nExample: Language immersion through K-dramas is a fun way to practice listening.\"},{\"heading\":\"Useful Phrases\",\"body\":\"1. Start by learning the alphabet first.\\n2. Practice speaking out loud every day.\\n3. Use flashcards to build your vocabulary.\\n4. Watch Korean shows with Korean subtitles.\\n5. Find a language exchange partner to practice conversation.\"}],\"exercises\":{\"fill_in_the_blanks\":[],\"translate_phrase\":[],\"answer_question\":[],\"multiple_choice\":[{\"prompt\":\"Choose the best term for the Korean writing system.\",\"question\":\"What is the name of the Korean alphabet?\",\"options\":[\"A) Hanja\",\"B) Hangul\",\"C) Katakana\",\"D) Romanization\"],\"correct_answer\":\"B) Hangul\",\"explanation\":\"Hangul is the official writing system of the Korean language.\"},{\"prompt\":\"Identify the best learning strategy.\",\"question\":\"Why is it recommended to stop using Romanization early?\",\"options\":[\"A) It makes reading faster.\",\"B) It can cause incorrect pronunciation.\",\"C) It is too difficult to write.\",\"D) It is only used in formal writing.\"],\"correct_answer\":\"B) It can cause incorrect pronunciation.\",\"explanation\":\"Romanization does not perfectly represent Korean sounds, so learning Hangul early improves pronunciation.\"},{\"prompt\":\"Understand language culture.\",\"question\":\"What are honorifics in Korean?\",\"options\":[\"A) Slang words used by teenagers.\",\"B) Grammatical markers used to show respect.\",\"C) Punctuation marks used in formal writing.\",\"D) Regional dialects spoken in Korea.\"],\"correct_answer\":\"B) Grammatical markers used to show respect.\",\"explanation\":\"Honorifics are crucial in Korean culture to show respect based on age and social status.\"},{\"prompt\":\"Apply learning techniques.\",\"question\":\"Which method is an example of language immersion?\",\"options\":[\"A) Translating every word into English.\",\"B) Watching Korean dramas without subtitles.\",\"C) Memorizing grammar rules from a textbook.\",\"D) Writing vocabulary words once a week.\"],\"correct_answer\":\"B) Watching Korean dramas without subtitles.\",\"explanation\":\"Immersion involves surrounding yourself with the natural language as it is spoken by natives.\"},{\"prompt\":\"Choose the best starting point.\",\"question\":\"What is the most practical first step for a beginner learning Korean?\",\"options\":[\"A) Memorizing complex grammar rules.\",\"B) Learning to read and write Hangul.\",\"C) Studying business vocabulary.\",\"D) Practicing advanced writing essays.\"],\"correct_answer\":\"B) Learning to read and write Hangul.\",\"explanation\":\"Learning Hangul is the foundation of reading, writing, and pronouncing Korean correctly.\"}]}}','2026-05-22 17:02:14',0,NULL),
(3,4,'learning python','English','English for Learning Python','{\"topic\":\"learning python\",\"language\":\"English\",\"title\":\"English for Learning Python\",\"sections\":[{\"heading\":\"Key Vocabulary\",\"body\":\"Syntax: The rules that say how a Python program must be written.\\nExample: You must follow the correct syntax to avoid errors.\\n\\nVariable: A named space used to store data or information.\\nExample: We created a variable to hold the user\'s age.\\n\\nFunction: A block of code that only runs when it is called.\\nExample: This function calculates the total price.\\n\\nDebug: To find and fix mistakes or bugs in your code.\\nExample: I need to debug my code because it keeps crashing.\\n\\nLibrary: A collection of pre-written code that you can use.\\nExample: We imported a library to help us build the website.\"},{\"heading\":\"Useful Phrases\",\"body\":\"1. How do I run this script?\\n2. I am getting a syntax error on line five.\\n3. Can you help me debug this function?\\n4. Which library should I use for this project?\\n5. I need to define a new variable.\"}],\"exercises\":{\"fill_in_the_blanks\":[],\"translate_phrase\":[],\"answer_question\":[],\"multiple_choice\":[{\"prompt\":\"Choose the best definition for the term syntax.\",\"question\":\"What does syntax mean in Python?\",\"options\":[\"A) A type of computer hardware\",\"B) The rules for how code must be written\",\"C) A mistake in the program\",\"D) A way to save your files\"],\"correct_answer\":\"B) The rules for how code must be written\",\"explanation\":\"Syntax refers to the specific rules of a programming language.\"},{\"prompt\":\"Select the correct meaning of debugging.\",\"question\":\"What do you do when you debug code?\",\"options\":[\"A) You delete the entire program\",\"B) You share your code online\",\"C) You find and fix errors in the code\",\"D) You write the code in a different language\"],\"correct_answer\":\"C) You find and fix errors in the code\",\"explanation\":\"Debugging is the process of locating and correcting bugs or errors.\"},{\"prompt\":\"Choose the most appropriate phrase for the situation.\",\"question\":\"Which phrase is best to use when you cannot get your code to work?\",\"options\":[\"A) How do I run this script?\",\"B) Can you help me debug this function?\",\"C) I need to define a new variable.\",\"D) Which library should I use?\"],\"correct_answer\":\"B) Can you help me debug this function?\",\"explanation\":\"This phrase directly asks for assistance with fixing a specific piece of code.\"},{\"prompt\":\"Identify the purpose of a variable.\",\"question\":\"What is a variable used for?\",\"options\":[\"A) To store data or information\",\"B) To connect to the internet\",\"C) To translate code to English\",\"D) To design a website layout\"],\"correct_answer\":\"A) To store data or information\",\"explanation\":\"A variable acts as a container for storing data values.\"},{\"prompt\":\"Understand the role of libraries in Python.\",\"question\":\"Why would a programmer import a library?\",\"options\":[\"A) To read a book about coding\",\"B) To use pre-written code for their project\",\"C) To buy new software\",\"D) To format their computer\"],\"correct_answer\":\"B) To use pre-written code for their project\",\"explanation\":\"Libraries contain reusable code that saves programmers from writing everything from scratch.\"}]}}','2026-05-22 17:09:13',0,NULL),
(4,6,'learning java','English','English for Learning Java','{\"topic\":\"Learning Java\",\"language\":\"English\",\"title\":\"English for Learning Java\",\"sections\":[{\"heading\":\"Key Vocabulary\",\"body\":\"Class: A blueprint or template used to create objects in Java.\\nExample: You need to define a class before creating an object.\\n\\nMethod: A block of code that performs a specific task or action.\\nExample: The print method displays text on the screen.\\n\\nVariable: A container that holds data while a Java program runs.\\nExample: We store the user\'s age in an integer variable.\\n\\nSyntax: The set of rules defining how a Java program is written.\\nExample: Missing a semicolon is a common syntax error.\\n\\nCompiler: A program that translates Java code into bytecode.\\nExample: The compiler checks your code for errors before running it.\"},{\"heading\":\"Useful Phrases\",\"body\":\"1. How do I debug this error?\\n2. Can you explain how this method works?\\n3. I need to declare a new variable here.\\n4. My code is not compiling.\\n5. Let\'s run the program and test it.\"}],\"exercises\":{\"fill_in_the_blanks\":[],\"translate_phrase\":[],\"answer_question\":[],\"multiple_choice\":[{\"prompt\":\"Choose the correct term based on the definition.\",\"question\":\"What is the blueprint used to create objects in Java?\",\"options\":[\"A) Method\",\"B) Variable\",\"C) Class\",\"D) Compiler\"],\"correct_answer\":\"C) Class\",\"explanation\":\"A class acts as a blueprint or template for creating objects in Java.\"},{\"prompt\":\"Choose the best phrase for the situation.\",\"question\":\"What do you say when your Java program has errors and cannot build?\",\"options\":[\"A) My code is not compiling.\",\"B) I need to declare a variable.\",\"C) How do I run this?\",\"D) The syntax is perfect.\"],\"correct_answer\":\"A) My code is not compiling.\",\"explanation\":\"We say code is not compiling when errors prevent the compiler from building the program.\"},{\"prompt\":\"Identify the correct programming concept.\",\"question\":\"What is a block of code that performs a specific task?\",\"options\":[\"A) Variable\",\"B) Method\",\"C) Syntax\",\"D) Class\"],\"correct_answer\":\"B) Method\",\"explanation\":\"A method is a specific block of code designed to execute a particular action.\"},{\"prompt\":\"Choose the correct term.\",\"question\":\"What is a container that holds data in a Java program?\",\"options\":[\"A) Compiler\",\"B) Syntax\",\"C) Method\",\"D) Variable\"],\"correct_answer\":\"D) Variable\",\"explanation\":\"A variable is used to store data values during program execution.\"},{\"prompt\":\"Choose the correct option.\",\"question\":\"What do we call the set of rules for writing Java code correctly?\",\"options\":[\"A) Syntax\",\"B) Debugging\",\"C) Compiling\",\"D) Object\"],\"correct_answer\":\"A) Syntax\",\"explanation\":\"Syntax refers to the specific rules governing the structure of a programming language.\"}]}}','2026-05-22 19:26:32',0,NULL),
(5,6,'android development','English','Declarative UI Paradigm & Core Compose Concepts','{\"topic\":\"android development\",\"language\":\"English\",\"title\":\"Declarative UI Paradigm & Core Compose Concepts\",\"sections\":[{\"heading\":\"Introduction to Declarative UI\",\"body\":\"In traditional Android development, the UI is imperative. You design layouts in XML and manually mutate views using methods like setText or setVisibility. Jetpack Compose introduces a declarative paradigm. Instead of modifying views directly, you describe what the UI should look like for a given state. When the state changes, the framework automatically updates the affected UI components.\"},{\"heading\":\"Composable Functions and Recomposition\",\"body\":\"Composable functions are the building blocks of Jetpack Compose. Annotated with @Composable, these functions transform data into UI. Recomposition is the process where Compose re-runs these functions with new data when state changes. Compose is intelligent: it only recomposes the specific components whose inputs have changed, ensuring high performance.\"},{\"heading\":\"Managing State with Remember and MutableStateOf\",\"body\":\"To trigger recomposition, Compose needs to observe state changes. We use mutableStateOf to create an observable State holder. However, because Composable functions run repeatedly during recomposition, local variables would reset. To prevent this, we wrap the state in a remember block, which instructs Compose to retain the value in memory across recompositions.\"},{\"heading\":\"Vocabulary\",\"body\":\"Declarative UI: A paradigm where you describe the UI based on current state. Imperative UI: A paradigm where you manually modify UI elements step-by-step. Composable Function: A Kotlin function annotated with @Composable that defines UI. Recomposition: The automatic re-execution of Composable functions to update the UI. State: Any value that can change over time and trigger UI updates. Remember: A Compose function that stores a value in memory across recompositions.\"},{\"heading\":\"Useful Phrases\",\"body\":\"The UI is a function of state. Recomposition only updates what changed. Use remember to preserve state. MutableStateOf creates observable state.\"}],\"exercises\":{\"fill_in_the_blanks\":[],\"translate_phrase\":[],\"answer_question\":[],\"multiple_choice\":[{\"prompt\":\"Identify the core difference between the two UI paradigms.\",\"question\":\"What is the main difference between imperative and declarative UI?\",\"options\":[\"Imperative UI describes what to display, while declarative UI describes how to build it.\",\"Declarative UI describes what the UI should look like for a given state, while imperative UI manually mutates views.\",\"Imperative UI is faster and uses less memory than declarative UI.\",\"Declarative UI requires XML files, whereas imperative UI is written purely in Kotlin.\"],\"correct_answer\":\"Declarative UI describes what the UI should look like for a given state, while imperative UI manually mutates views.\",\"explanation\":\"Declarative UI focuses on describing the current state of the UI, while imperative UI requires step-by-step manual updates to the view hierarchy.\"},{\"prompt\":\"Understand how Compose updates the screen.\",\"question\":\"What triggers a recomposition in Jetpack Compose?\",\"options\":[\"Manually calling an invalidate method on the screen.\",\"A change in an observed State object.\",\"Restarting the Android application.\",\"Modifying the underlying XML layout file.\"],\"correct_answer\":\"A change in an observed State object.\",\"explanation\":\"Compose observes State objects; when their value changes, Compose automatically schedules a recomposition for the affected composables.\"},{\"prompt\":\"Learn the purpose of state retention.\",\"question\":\"Why is the remember function used in Jetpack Compose?\",\"options\":[\"To cache network responses on the disk.\",\"To store a value in memory across recompositions.\",\"To prevent the application from crashing during configuration changes.\",\"To force a recomposition of the entire screen.\"],\"correct_answer\":\"To store a value in memory across recompositions.\",\"explanation\":\"Without remember, local variables in a Composable function would reset to their initial values every time the function recomposes.\"},{\"prompt\":\"Identify Composable syntax.\",\"question\":\"How do you declare a function as a Composable in Jetpack Compose?\",\"options\":[\"By inheriting from the Composable base class.\",\"By annotating the function with @Composable.\",\"By naming the function starting with the word composable.\",\"By registering the function in the AndroidManifest file.\"],\"correct_answer\":\"By annotating the function with @Composable.\",\"explanation\":\"The @Composable annotation tells the Compose compiler plugin that this function is intended to convert data into UI.\"},{\"prompt\":\"Analyze local state behavior.\",\"question\":\"What happens to a local variable inside a Composable if it is not wrapped in remember?\",\"options\":[\"It retains its value perfectly during recomposition.\",\"It resets to its initial value during recomposition.\",\"It causes a compilation error immediately.\",\"It is automatically saved to the device storage.\"],\"correct_answer\":\"It resets to its initial value during recomposition.\",\"explanation\":\"Because recomposition re-runs the Composable function, any local variable not wrapped in remember will be re-initialized.\"}]}}','2026-05-22 19:49:56',0,NULL),
(6,4,'korean language','English','Essential Korean Phrases and Vocabulary for Beginners','{\"topic\":\"Korean Language\",\"language\":\"English\",\"title\":\"Essential Korean Phrases and Vocabulary for Beginners\",\"sections\":[{\"heading\":\"Key Vocabulary\",\"body\":\"Annyeonghaseyo: Hello\\nExample: You say Annyeonghaseyo when meeting your teacher.\\n\\nKamsahamnida: Thank you\\nExample: Say Kamsahamnida when someone gives you a gift.\\n\\nJuseyo: Please give me\\nExample: Use Juseyo when ordering food at a restaurant.\\n\\nOlmaeyo: How much is it?\\nExample: Ask Olmaeyo when shopping at a market.\\n\\nYe: Yes\\nExample: Say Ye to agree with someone politely.\"},{\"heading\":\"Useful Phrases\",\"body\":\"1. Annyeonghi gyeseyo: Goodbye\\n2. Chogiyo: Excuse me\\n3. Mul juseyo: Water, please\\n4. Hwajangsil odiyeyo: Where is the restroom?\"}],\"exercises\":{\"fill_in_the_blanks\":[],\"translate_phrase\":[],\"answer_question\":[],\"multiple_choice\":[{\"prompt\":\"Choose the correct word to say thank you.\",\"question\":\"How do you say thank you politely in Korean?\",\"options\":[\"A) Annyeonghaseyo\",\"B) Kamsahamnida\",\"C) Juseyo\",\"D) Olmaeyo\"],\"correct_answer\":\"B) Kamsahamnida\",\"explanation\":\"Kamsahamnida is the standard polite way to express gratitude in Korean.\"},{\"prompt\":\"Choose the correct phrase to ask for the restroom.\",\"question\":\"Which phrase means Where is the restroom?\",\"options\":[\"A) Mul juseyo\",\"B) Chogiyo\",\"C) Hwajangsil odiyeyo\",\"D) Annyeonghi gyeseyo\"],\"correct_answer\":\"C) Hwajangsil odiyeyo\",\"explanation\":\"Hwajangsil means restroom and odiyeyo means where is it.\"},{\"prompt\":\"Identify the correct word to ask for something.\",\"question\":\"What word do you add to the end of a noun to say please give me?\",\"options\":[\"A) Juseyo\",\"B) Ye\",\"C) Olmaeyo\",\"D) Chogiyo\"],\"correct_answer\":\"A) Juseyo\",\"explanation\":\"Juseyo is used to politely request items in Korean.\"},{\"prompt\":\"Choose the correct phrase to get a waiter\'s attention.\",\"question\":\"What should you say to get someone\'s attention in a restaurant?\",\"options\":[\"A) Ye\",\"B) Kamsahamnida\",\"C) Chogiyo\",\"D) Annyeonghi gyeseyo\"],\"correct_answer\":\"C) Chogiyo\",\"explanation\":\"Chogiyo translates to excuse me and is used to get attention.\"},{\"prompt\":\"Choose the correct phrase for asking the price.\",\"question\":\"How do you ask how much an item costs?\",\"options\":[\"A) Hwajangsil odiyeyo\",\"B) Olmaeyo\",\"C) Mul juseyo\",\"D) Annyeonghaseyo\"],\"correct_answer\":\"B) Olmaeyo\",\"explanation\":\"Olmaeyo is the standard polite way to ask for the price of something.\"}]}}','2026-05-22 19:57:35',0,NULL),
(7,4,'kotlin language','English','Kotlin Syntax and Type System Basics','{\"topic\":\"kotlin language\",\"language\":\"English\",\"title\":\"Kotlin Syntax and Type System Basics\",\"sections\":[{\"heading\":\"Core Vocabulary\",\"body\":\"Let us look at the essential terms for today:\\n\\n1. Read-only: A variable that cannot be reassigned after it is initialized. In Kotlin, we declare this using \'val\'.\\n2. Mutable: A variable whose value can be changed or reassigned. In Kotlin, we declare this using \'var\'.\\n3. Nullable: A type that can hold a null value. In Kotlin, we mark a type as nullable by adding a question mark, like String?.\\n4. Type Inference: The compiler\'s ability to automatically detect the data type of a variable without you writing it explicitly.\\n5. NullPointerException (NPE): A common runtime error that occurs when an application attempts to use null where an object is required. Kotlin\'s type system is designed to eliminate this.\"},{\"heading\":\"Useful Phrases for Discussing Kotlin\",\"body\":\"Use these phrases to describe your code:\\n\\n- \'We declare a read-only variable using val.\'\\n- \'This variable is mutable, so we can reassign its value later.\'\\n- \'By default, Kotlin types are non-nullable.\'\\n- \'The compiler uses type inference to determine that this is an Int.\'\\n- \'Kotlin prevents NullPointerExceptions at compile time.\'\"}],\"exercises\":{\"fill_in_the_blanks\":[],\"translate_phrase\":[],\"answer_question\":[],\"multiple_choice\":[{\"prompt\":\"Choose the correct keyword for a read-only variable.\",\"question\":\"Which keyword do you use to declare a read-only variable in Kotlin?\",\"options\":[\"var\",\"val\",\"const\",\"let\"],\"correct_answer\":\"val\",\"explanation\":\"The \'val\' keyword is used to declare a read-only variable, meaning its value cannot be reassigned once initialized.\"},{\"prompt\":\"Identify the meaning of the question mark in Kotlin types.\",\"question\":\"What does the type \'String?\' mean in Kotlin?\",\"options\":[\"The variable is a query\",\"The variable is mutable\",\"The variable is nullable\",\"The variable is empty\"],\"correct_answer\":\"The variable is nullable\",\"explanation\":\"A question mark after a type indicates that the variable can hold either a String value or null.\"},{\"prompt\":\"Understand how Kotlin handles null safety.\",\"question\":\"How does Kotlin prevent NullPointerExceptions (NPE)?\",\"options\":[\"By making all variables mutable\",\"By distinguishing between nullable and non-nullable types at compile time\",\"By converting all null values to empty strings\",\"By ignoring null values during execution\"],\"correct_answer\":\"By distinguishing between nullable and non-nullable types at compile time\",\"explanation\":\"Kotlin\'s compiler checks null safety at compile time, forcing developers to handle nullable values safely before the code runs.\"},{\"prompt\":\"Identify the term for automatic type detection.\",\"question\":\"What is the term for when the Kotlin compiler automatically detects the type of a variable?\",\"options\":[\"Type Casting\",\"Type Inference\",\"Type Safety\",\"Type Mutation\"],\"correct_answer\":\"Type Inference\",\"explanation\":\"Type inference allows you to omit the explicit type declaration because the compiler can figure it out from the assigned value.\"},{\"prompt\":\"Differentiate between val and var.\",\"question\":\"Which of the following statements is true about \'var\'?\",\"options\":[\"It creates a read-only variable\",\"It creates a mutable variable\",\"It cannot be reassigned\",\"It is only used for nullable types\"],\"correct_answer\":\"It creates a mutable variable\",\"explanation\":\"Variables declared with \'var\' are mutable, which means their values can be changed or reassigned during program execution.\"}]}}','2026-05-22 19:58:42',0,NULL),
(8,4,'Airport and travel phrases','English','Essential Airport and Travel English','{\"topic\":\"Airport and travel phrases\",\"language\":\"English\",\"title\":\"Essential Airport and Travel English\",\"sections\":[{\"heading\":\"Key Vocabulary\",\"body\":\"Boarding pass: A document giving permission to get on a plane\\nExample: Please show your boarding pass at the gate.\\n\\nCarry-on: A small bag you take inside the plane with you\\nExample: Keep your passport in your carry-on bag.\\n\\nLayover: A temporary stop between parts of a journey\\nExample: We have a three-hour layover in Chicago.\\n\\nGate: The area where passengers board their airplane\\nExample: Flight 402 is boarding at gate 12.\\n\\nBaggage claim: The area where you collect your luggage after a flight\\nExample: Head to baggage claim to pick up your suitcases.\"},{\"heading\":\"Useful Phrases\",\"body\":\"1. Where is the check-in desk for this airline?\\n2. I would like an aisle seat, please.\\n3. Is this bag small enough for a carry-on?\\n4. What time does boarding start?\\n5. My flight has been delayed.\"}],\"exercises\":{\"fill_in_the_blanks\":[],\"translate_phrase\":[],\"answer_question\":[],\"multiple_choice\":[{\"prompt\":\"Choose the correct word to complete the sentence.\",\"question\":\"You must show your ... before you can get on the airplane.\",\"options\":[\"A) boarding pass\",\"B) baggage claim\",\"C) layover\",\"D) gate\"],\"correct_answer\":\"A) boarding pass\",\"explanation\":\"A boarding pass is the official document that allows you to board the plane.\"},{\"prompt\":\"Choose the best response for the situation.\",\"question\":\"You want to ask where to collect your luggage after landing. What do you say?\",\"options\":[\"A) Where is the gate?\",\"B) Where is the baggage claim?\",\"C) Where is the check-in desk?\",\"D) Where is the layover?\"],\"correct_answer\":\"B) Where is the baggage claim?\",\"explanation\":\"Baggage claim is the designated area where you collect your suitcases after a flight.\"},{\"prompt\":\"Choose the correct word to complete the sentence.\",\"question\":\"We have a short ... in Paris before our final flight to Rome.\",\"options\":[\"A) carry-on\",\"B) gate\",\"C) layover\",\"D) boarding pass\"],\"correct_answer\":\"C) layover\",\"explanation\":\"A layover is a temporary stop at an intermediate airport during a journey.\"},{\"prompt\":\"Choose the best option.\",\"question\":\"If you want a seat next to the corridor, you should ask for an ...\",\"options\":[\"A) window seat\",\"B) middle seat\",\"C) aisle seat\",\"D) gate seat\"],\"correct_answer\":\"C) aisle seat\",\"explanation\":\"An aisle seat is located next to the walkway or corridor on the plane.\"},{\"prompt\":\"Choose the correct word to complete the sentence.\",\"question\":\"Please keep your personal items in your ... bag.\",\"options\":[\"A) layover\",\"B) carry-on\",\"C) gate\",\"D) boarding pass\"],\"correct_answer\":\"B) carry-on\",\"explanation\":\"A carry-on bag is the small luggage you are allowed to bring onto the plane with you.\"}]}}','2026-05-22 19:59:14',0,NULL),
(9,7,'java for banking','English','Banking Domain Vocabulary and Java Mapping','{\"topic\":\"java for banking\",\"language\":\"English\",\"title\":\"Banking Domain Vocabulary and Java Mapping\",\"sections\":[{\"heading\":\"Core Banking Vocabulary\",\"body\":\"In banking software, precise terminology is critical. A Ledger is the principal book or computer file for recording financial transactions. A Transaction represents an exchange of funds, which we model as a Java class with fields like ID, amount, and timestamp. Account Types define the category of a bank account, such as Savings or Checking. To represent these fixed categories in Java, we use Enums. For monetary values, we never use float or double because they cause rounding errors. Instead, we use BigDecimal, a Java class designed for high-precision arithmetic. Finally, Currency represents the monetary system used, often mapped using the java.util.Currency class.\"},{\"heading\":\"Useful Phrases for Developers\",\"body\":\"When discussing banking code, use these standard phrases: 1. We must use BigDecimal instead of double to prevent rounding errors in financial calculations. 2. The Ledger class maintains a list of all posted transactions. 3. We define account types like checking and savings using a Java Enum. 4. Each transaction requires a unique identifier and a precise timestamp.\"}],\"exercises\":{\"fill_in_the_blanks\":[],\"translate_phrase\":[],\"answer_question\":[],\"multiple_choice\":[{\"prompt\":\"Choose the correct data type for financial calculations.\",\"question\":\"Why should you use BigDecimal instead of double for monetary values in Java?\",\"options\":[\"BigDecimal is faster to execute\",\"Double causes rounding errors due to floating-point representation\",\"BigDecimal uses less memory\",\"Double is not supported in modern Java versions\"],\"correct_answer\":\"Double causes rounding errors due to floating-point representation\",\"explanation\":\"Floating-point types like double cannot represent base-10 decimals precisely, leading to dangerous rounding errors in financial calculations.\"},{\"prompt\":\"Identify the best Java construct for fixed categories.\",\"question\":\"Which Java construct is best suited to represent fixed account types like CHECKING and SAVINGS?\",\"options\":[\"String\",\"int\",\"Enum\",\"ArrayList\"],\"correct_answer\":\"Enum\",\"explanation\":\"Enums are perfect for representing a fixed set of constants, ensuring type safety and preventing invalid values.\"},{\"prompt\":\"Understand core banking concepts.\",\"question\":\"What does a Ledger represent in a banking application?\",\"options\":[\"A database connection pool\",\"A record-keeping system for transactions\",\"A user interface component\",\"An encryption algorithm\"],\"correct_answer\":\"A record-keeping system for transactions\",\"explanation\":\"A ledger is the system of record where all financial transactions are logged and totaled.\"},{\"prompt\":\"Identify correct Java instantiation for currency.\",\"question\":\"How should a transaction amount of 100.50 be declared in a Java class?\",\"options\":[\"double amount = 100.50;\",\"float amount = 100.50f;\",\"BigDecimal amount = new BigDecimal(\\\"100.50\\\");\",\"int amount = 10050;\"],\"correct_answer\":\"BigDecimal amount = new BigDecimal(\\\"100.50\\\");\",\"explanation\":\"Instantiating BigDecimal with a String constructor avoids floating-point inaccuracies and is the standard practice for monetary values.\"},{\"prompt\":\"Understand the purpose of transaction modeling.\",\"question\":\"What is the primary purpose of a Transaction object in Java banking software?\",\"options\":[\"To manage user login sessions\",\"To represent a single movement of funds\",\"To generate PDF statements\",\"To connect to the main server\"],\"correct_answer\":\"To represent a single movement of funds\",\"explanation\":\"A transaction object models the transfer of money between accounts or parties, containing details like source, destination, and amount.\"}]}}','2026-05-22 20:02:36',0,NULL),
(10,9,'Python','English','Pythonic Code & Core Terminology','{\"topic\":\"Python\",\"language\":\"English\",\"title\":\"Pythonic Code & Core Terminology\",\"sections\":[{\"heading\":\"Introduction to Pythonic Code\",\"body\":\"Writing Pythonic code means adopting the philosophy of readability and simplicity. The PEP 8 style guide provides rules to keep code clean, such as using four spaces for indentation and naming variables in snake_case. When we write idiomatic code, we use Python\'s unique features to make our programs clear and efficient.\"},{\"heading\":\"Comprehensions and Generators\",\"body\":\"Instead of using long loops to build collections, Python offers comprehensions. A list comprehension looks like [x for x in items]. A dict comprehension looks like {k: v for k, v in items}. For large datasets, we use generator expressions, written with parentheses (x for x in items). Generators use lazy evaluation, meaning they produce items one at a time, keeping the memory footprint very low.\"},{\"heading\":\"Core Vocabulary\",\"body\":\"Pythonic: Code that conforms to common Python design patterns and philosophy. Comprehension: A concise syntax for creating collections from existing iterables. Generator Expression: A memory-efficient, lazy-evaluated tool for creating iterators. PEP 8: The official style guide for writing readable Python code. Refactoring: Reorganizing existing code without changing its external behavior. Idiomatic: Using the natural expressions and patterns of a programming language.\"},{\"heading\":\"Useful Phrases\",\"body\":\"Write readable code: To produce code that is easy for others to understand. Memory footprint: The amount of memory a program uses during execution. Adhere to style guidelines: To follow established coding standards like PEP 8. Lazy evaluation: Delaying the evaluation of an expression until its value is needed. Code smell: Any symptom in the source code that possibly indicates a deeper problem.\"}],\"exercises\":{\"fill_in_the_blanks\":[],\"translate_phrase\":[],\"answer_question\":[],\"multiple_choice\":[{\"prompt\":\"Identify the term that describes code that is readable, clean, and follows standard Python practices.\",\"question\":\"What do we call code that is written in a style that fits exceptionally well with Python\'s design philosophy?\",\"options\":[\"Pythonic\",\"Systemic\",\"Compiled\",\"Monolithic\"],\"correct_answer\":\"Pythonic\",\"explanation\":\"Pythonic code is idiomatic code that follows the style and philosophy of the Python language, emphasizing readability and simplicity.\"},{\"prompt\":\"Select the correct syntax for a memory-efficient generator expression.\",\"question\":\"Which of the following represents a generator expression rather than a list comprehension?\",\"options\":[\"[x for x in range(10)]\",\"{x for x in range(10)}\",\"(x for x in range(10))\",\"list(x for x in range(10))\"],\"correct_answer\":\"(x for x in range(10))\",\"explanation\":\"Generator expressions use parentheses instead of square brackets, allowing for lazy evaluation and a smaller memory footprint.\"},{\"prompt\":\"Understand the purpose of Python\'s style guide.\",\"question\":\"What is the primary goal of the PEP 8 style guide?\",\"options\":[\"To make Python code run faster\",\"To improve the readability of Python code\",\"To define database connection rules\",\"To compile Python into machine code\"],\"correct_answer\":\"To improve the readability of Python code\",\"explanation\":\"PEP 8 is the official style guide for Python, designed to improve code readability and consistency across different developers\' codebases.\"},{\"prompt\":\"Choose the correct dict comprehension syntax.\",\"question\":\"How would you write a dict comprehension to square numbers from 1 to 3?\",\"options\":[\"{x: x*x for x in range(1, 4)}\",\"[x: x*x for x in range(1, 4)]\",\"(x: x*x for x in range(1, 4))\",\"dict(x, x*x for x in range(1, 4))\"],\"correct_answer\":\"{x: x*x for x in range(1, 4)}\",\"explanation\":\"Dict comprehensions use curly braces with a key-value pair format separated by a colon.\"},{\"prompt\":\"Identify the concept of lazy evaluation.\",\"question\":\"What is the main benefit of using lazy evaluation in generator expressions?\",\"options\":[\"It speeds up the CPU clock rate\",\"It loads all items into memory immediately\",\"It generates values on the fly, reducing memory usage\",\"It automatically formats the code to PEP 8 standards\"],\"correct_answer\":\"It generates values on the fly, reducing memory usage\",\"explanation\":\"Lazy evaluation delays computation until the value is actually needed, which keeps the memory footprint low.\"}]}}','2026-05-23 05:46:51',0,NULL);
